const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const supe = @import("tasksuper"); const tick = @import("tk-task-tick.zig");
const tszz = std.testing; const Sche = tick.Sche; const CF = tick.CF;
fn plusJson(allo: std.mem.Allocator, json: []const u8) std.json.Value { return std.json.parseFromSliceLeaky(std.json.Value, allo, json, .{}) catch unreachable; }
test "cloneJob re-points every slice into the copy, not the source" { var srcz: Sche.Jobz = .{}; srcz.iden = Sche.intoDupe(&srcz.iden_buff, "job-1"); srcz.runz = Sche.intoDupe(&srcz.runz_buff, "echo hi"); srcz.queu_file = Sche.intoDupe(&srcz.queu_file_buff, "a.txt"); srcz.once_stam = Sche.intoDupe(&srcz.once_buff, "2026-10-07 09:00"); const pntr = try Sche.jobzClon(tszz.allocator, &srcz); defer tszz.allocator.destroy(pntr); @memset(&srcz.iden_buff, 'X'); @memset(&srcz.runz_buff, 'X'); try tszz.expectEqualStrings("job-1", pntr.iden); try tszz.expectEqualStrings("echo hi", pntr.runz); try tszz.expectEqualStrings("a.txt", pntr.queu_file); try tszz.expectEqualStrings("2026-10-07 09:00", pntr.once_stam); try tszz.expectEqual(@as(usize, 0), pntr.cwdz.len); }
test "enqueue coalesces a task that is already queued" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; sche.stop.store(true, .release); defer sche.dein(); var joba: Sche.Jobz = .{}; joba.iden = Sche.intoDupe(&joba.iden_buff, "same"); var jobb: Sche.Jobz = .{}; jobb.iden = Sche.intoDupe(&jobb.iden_buff, "same"); var jobc: Sche.Jobz = .{}; jobc.iden = Sche.intoDupe(&jobc.iden_buff, "other"); const pnta = try Sche.jobzClon(tszz.allocator, &joba); const pntb = try Sche.jobzClon(tszz.allocator, &jobb); const pntc = try Sche.jobzClon(tszz.allocator, &jobc); defer tszz.allocator.destroy(pntb); try tszz.expect(sche.queuEnqu(iozz, pnta)); try tszz.expect(!sche.queuEnqu(iozz, pntb)); try tszz.expect(sche.queuEnqu(iozz, pntc)); try tszz.expectEqual(@as(usize, 2), sche.queu.items.len); var wait: u32 = 0; while (sche.workBusy(iozz) and wait < 2000) : (wait += 10) std.Io.sleep(iozz, .fromMilliseconds(10), .awake) catch {}; try tszz.expect(!sche.workBusy(iozz)); }
test "pickLocked: same lock waits its turn, other locks and \"none\" do not" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; defer sche.queu.deinit(tszz.allocator); var joba: Sche.Jobz = .{}; joba.iden = Sche.intoDupe(&joba.iden_buff, "a"); joba.lock = Sche.intoDupe(&joba.lock_buff, "main"); var jobb: Sche.Jobz = .{}; jobb.iden = Sche.intoDupe(&jobb.iden_buff, "b"); jobb.lock = Sche.intoDupe(&jobb.lock_buff, "main"); var jobc: Sche.Jobz = .{}; jobc.iden = Sche.intoDupe(&jobc.iden_buff, "c"); jobc.lock = Sche.intoDupe(&jobc.lock_buff, "none"); try sche.queu.append(tszz.allocator, &joba); try sche.queu.append(tszz.allocator, &jobb); try sche.queu.append(tszz.allocator, &jobc); sche.runn[0] = .{ .acti = true }; sche.runn[0].iden_leng = Sche.intoDupe(&sche.runn[0].iden_buff, "a").len; sche.runn[0].lock_leng = Sche.intoDupe(&sche.runn[0].lock_buff, "main").len; _ = sche.queu.orderedRemove(0); const pick = sche.lockPick(0).?; try tszz.expectEqualStrings("c", pick.iden); try tszz.expect(sche.lockPick(0) == null); sche.runn[0].acti = false; jobb.notz_befo_msec = 1000; try tszz.expect(sche.lockPick(999) == null); try tszz.expectEqualStrings("b", sche.lockPick(1000).?.iden); }
test "lastRunOf answers from the write-through cache, no log file needed" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var sche: Sche = .{}; sche.gpaz = tszz.allocator; defer sche.dein(); const nowz: time.Local = .{ .year = 2026, .month = 10, .day = 7, .hour = 9, .minute = 5, .second = 3, .weekday = 3, .minute_stamp = 0 }; sche.runzNote(iozz, "no-such-log-task-zz", .{ .code = 7, .elap_msec = 42 }, nowz); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const last = sche.runzLast(aren.allocator(), iozz, "no-such-log-task-zz").?; try tszz.expectEqual(@as(i32, 7), last.code); try tszz.expectEqual(@as(i64, 42), last.elap_msec); try tszz.expectEqualStrings("2026-10-07 09:05:03", last.when); }
